<template>
  <div class="table-container">
    <div class="bpm-list">
      <div class="card-container" :style="containerStyle">
        <div v-for="(mainGroup, mainIndex) in sortedCardList" :key="mainIndex" class="card-group">
          <div class="group-title">
            {{ Number(mainGroup.mainBpm) }}
          </div>
          <div v-for="(subItem, subIndex) in mainGroup.subBpmList" :key="subIndex" class="sub-bpm-row">
            <div class="content-wrapper">
              <div class="sub-bpm-label">
                {{ subItem.subBpm }}
              </div>
              <div class="card-grid" :style="getGridStyle()">
                <div 
                  v-for="(item, idx) in subItem.contentList" 
                  :key="idx"
                >
                  <bpmCard :chart-info="item" />
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, onMounted, computed } from 'vue'
import bpmCard from './components/bpmCard.vue'
import bpmGet from './components/bpmGet.vue'

const bpmList = ref([])

const parseBpmData = (rawData) => {
  if (!Array.isArray(rawData)) return []
  return rawData.map(item => {
    const [mainBpm, subBpmObj] = item
    const subBpmList = Object.entries(subBpmObj).map(([subBpm, contentList]) => ({
      subBpm,
      contentList
    }))
    return {
      mainBpm: Number(mainBpm),
      subBpmList
    }
  })
}

const columns = ref(6)
const gap = ref(20)
const gridWidth = ref('100%')

const containerStyle = computed(() => {
  return {
    width: typeof gridWidth.value === 'number' ? `${gridWidth.value}px` : gridWidth.value,
    margin: '0 auto',
    boxSizing: 'border-box'
  }
})

const getGridStyle = () => {
  return {
    '--column-count': columns.value,
    '--gap-size': `${gap.value}px`,
    '--column-width': `calc((100% - (var(--column-count) - 1) * var(--gap-size)) / var(--column-count))`
  }
}

const sortedCardList = computed(() => {
  const sortedGroups = [...bpmList.value].sort((a, b) => {
    const numA = Number(a.mainBpm)
    const numB = Number(b.mainBpm)
    return numB - numA
  })
  return sortedGroups.map(group => ({
    ...group,
    subBpmList: [...group.subBpmList].sort((a, b) => {
      const numA = Number(a.subBpm.replace('x', ''))
      const numB = Number(b.subBpm.replace('x', ''))
      return numA - numB
    })
  }))
})

onMounted(async () => {
  try {
    const rawBpmData = await bpmGet.methods.getBPM()
    bpmList.value = parseBpmData(rawBpmData)
  } catch (error) {
    console.error('BPM列表加载失败：', error)
  }
})
</script>

<style scoped>
.table-container {
  width: 100%;
  padding: 0.16rem;
  box-sizing: border-box;
}

.bpm-list {
  margin-top: 0.2rem;
}

.card-container {
  width: 100%;
  box-sizing: border-box;
}

.card-group {
  width: 100%;
  margin-bottom: 0.24rem;
  box-sizing: border-box;
}

.group-title {
  height: 0.3rem;
  line-height: 0.3rem;
  background-color: var(--color-bg-sub);
  color: var(--color-text);
  padding: 0 0.16rem;
  font-size: 0.16rem;
  font-weight: 600;
  margin-bottom: 0.08rem;
  box-sizing: border-box;
  text-align: center;
  user-select: none;
}

.sub-bpm-row {
  width: 100%;
  margin-bottom: 0.16rem;
  box-sizing: border-box;
  user-select: none;
}

.content-wrapper {
  display: flex;
  align-items: stretch;
  width: 100%;
  box-sizing: border-box;
  min-height: 0.8rem;
}

.sub-bpm-label {
  width: 0.3rem;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0.08rem 0.16rem;
  background-color: var(--color-bg-sub);
  color: var(--color-text);
  font-size: 0.18rem;
  font-weight: 50;
  box-sizing: border-box;
  word-break: break-word;
  flex-shrink: 0;
}

.card-grid {
  flex: 1;
  display: flex;
  flex-wrap: wrap;
  gap: var(--gap-size);
  box-sizing: border-box;
  padding: 0.08rem;
  border-left: none;
  border-radius: 0 0.04rem 0.04rem 0;
}

.card-grid > * {
  width: var(--column-width) !important;
  flex-shrink: 0;
  box-sizing: border-box;
}
</style>