<script>
import axios from 'axios'

export default {
  name: 'AccountGet',
  methods: {
    async getAccount() {
      const net = '' 
      const net_files = `${net}/files`
      const jsonFile = `${net_files}/infos/account.json`
      try {
        const response = await axios.get(jsonFile)
        const jsonData = response.data
        return jsonData;
      } catch (error) {
        console.error('获取数据失败：', error);
        console.error('实际请求的JSON文件路径：', jsonFile);
        return {};
      }
    }
  }
}
</script>