<script setup>
import accountGet from './components/accountGet.vue'
import { ref, onMounted } from 'vue'
import { useRouter } from 'vue-router'

const router = useRouter()
const userData = ref({})

const setRem = () => {
  const designWidth = 1550
  const clientWidth = document.documentElement.clientWidth
  const fontSize = (clientWidth / designWidth) * 100
  document.documentElement.style.fontSize = fontSize + 'px'
}

onMounted(() => {
  setRem()
  window.addEventListener('resize', setRem)
  accountGet.methods.getAccount().then(data => {
    userData.value = data
  })
})

const goToTable = (tableName) => {
  router.push({ name: tableName })
}

const handleUserLink = (link) => {
  if (link.startsWith('/') || !link.includes('http')) {
    goToTable(link)
  } else {
    window.open(link, '_blank')
  }
}
</script>

<template>
  <div class="user-container">
    <div v-for="(userList, category) in userData" :key="category" class="category-section">
      <h2 class="category-title">{{ category }}</h2>
      <div class="user-card-container">
        <div 
          class="user-card" 
          v-for="(user, index) in userList" 
          :key="index"
          @click="handleUserLink('https://space.bilibili.com/' + user[1])"
        >
          <div class="user-info">
            <h3 class="user-name">@{{ user[0] }}</h3>
            <p class="user-desc">{{ user[2] }}</p>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<style scoped>
.user-container {
  max-width: 15rem;
  margin: 0 auto;
  padding: 0.2rem;
}

.category-section {
  margin-bottom: 0.4rem;
}

.category-title {
  font-size: 0.28rem;
  color: #6c90e5;
  margin: 0 0 0.2rem 0;
  padding-bottom: 0.1rem;
  border-bottom: 0.02rem solid #6c90e5;
  user-select: none;
}

.user-card-container {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(20%, 1fr));
  gap: 0.2rem;
  padding: 0.1rem 0;
}

.user-card {
  display: flex;
  align-items: center;
  gap: 0.15rem;
  padding: 0.15rem;
  background-color: var(--color-bg-sub);
  cursor: pointer;
  user-select: none;
}

.user-info {
  flex: 1;
  overflow: hidden;
}

.user-name {
  margin: 0 0 0.08rem 0;
  font-size: 0.22rem;
  color: #6c90e5;
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.user-desc {
  margin: 0;
  font-size: 0.15rem;
  color: #d2d2d2;
  line-height: 1.4;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
</style>